// AccountBean PropertyChangeListener
import java.beans.*;public class Q06 {public static class AccountBean {private double balance;private final PropertyChangeSupport changes=new PropertyChangeSupport(this);public AccountBean(){}public double getBalance(){return balance;}public void setBalance(double v){double old=balance;balance=v;changes.firePropertyChange("balance",old,v);}public void addPropertyChangeListener(PropertyChangeListener l){changes.addPropertyChangeListener(l);}}public static void main(String[] args){AccountBean account=new AccountBean();account.addPropertyChangeListener(e->System.out.println(e.getPropertyName()+" changed from "+e.getOldValue()+" to "+e.getNewValue()));account.setBalance(100);}}
